UPDATE clients c
SET
  experian_username    = s.experian_username,
  experian_password    = s.experian_password,
  equifax_pin          = s.equifax_pin,
  smartcredit_username = s.smartcredit_username,
  smartcredit_password = s.smartcredit_password
FROM bureau_logins_staging s
WHERE LOWER(c.email) = LOWER(s.email)
   OR LOWER(c.name)  = LOWER(s.fullname);

SELECT COUNT(*) AS clients_updated FROM clients WHERE experian_username IS NOT NULL;
